{
    char co = 0;
    switch (c)
    {
    case 'n':
        co = '\n';
        break;
    case '\\':
        co = '\\';
        break;
    case 't':
        co = '\t';
        break;
    case 'b':
        co = '\b';
        break;
    case '\'':
        co = '\'';
        break;
    }
    return co;
}

